    X("economics-1-2", type="mcq", id="q-ec-1-pa05", stem_zh="按配方工作并领取报酬，主要提供的是？", stem_en="Working to a recipe and being paid mainly provides:", answer="d", exp_zh="劳动。", exp_en="Labour.", options=opts(("土地", "land"), ("汇率政策", "exchange-rate policy"), ("公共物品", "a public good"), ("劳动", "labour"))),
