    X("economics-1-3", type="mcq", id="q-ec-1-pa07", stem_zh="PPC 以外的点在当前资源与技术下？", stem_en="A point outside the PPC, with current resources and technology, is:", answer="b", exp_zh="无法达到。", exp_en="Unreachable.", options=opts(("已经被实现", "already achieved"), ("无法达到", "unreachable"), ("表示失业", "a sign of unemployment"), ("与机会成本无关", "unrelated to opportunity cost"))),
