    X("economics-6-3", type="mcq", id="q-ec-6-pr05", stem_zh="本币升值意味着？", stem_en="An appreciation of the home currency means that:", answer="d", exp_zh="同样的本币能换得更多外币。", exp_en="The same amount of home currency buys more foreign currency.", options=opts(("同样的本币只能换得更少外币", "the same amount of home currency buys less foreign currency"), ("货币不再具有交换媒介职能", "money no longer functions as a medium of exchange"), ("配额自动取消", "quotas are cancelled automatically"), ("同样的本币能换得更多外币", "the same amount of home currency buys more foreign currency"))),
